def _is_path(q: str) -> bool:
    """A typed absolute path: ``/…`` as on the web, and ``C:/…`` or ``C:\\…`` for Windows folders."""
    return q.startswith("/") or re.match(r"^[A-Za-z]:[\\/]", q) is not None


