Json = Dict[str, Any]

TREE_W = 212
ROW_H = 26
INDENT = 16  # one step of nesting; files sit after the space a folder's chevron takes


@dataclass
class Tab:
    path: str
    doc: str = ""
    saved: str = ""
    mtime: Optional[float] = None
    binary: bool = False
    data_url: Optional[str] = None
    too_large: bool = False
