            self.viewport().update()

    def leaveEvent(self, e) -> None:  # noqa: N802
        self._hover = -1
        self.viewport().update()
        super().leaveEvent(e)

    def mousePressEvent(self, e: QMouseEvent) -> None:  # noqa: N802
        if e.button() != Qt.MouseButton.LeftButton:
            return super().mousePressEvent(e)
