    def _on_rt(self, sid: str) -> None:
        if sid != self.sid:
            return
        self.render()
        self._schedule_git()

    def _on_ui(self) -> None:
        ui = store.ui
        self.side_btn.setVisible(not ui.sidebar)
        self.panel_btn.set_active(ui.panel)
