  }, [status, load]);
  const fsRev = useStore((s) => s.fsRev);
  useEffect(() => {
    if (fsRev) load();
  }, [fsRev]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (Date.now() - lastLoad.current < 2500) return;
    const t = setTimeout(load, 1200);
    return () => clearTimeout(t);
