      if (!entries.length) continue;
      parts.push(`${path}`);
      for (const [key, n] of entries) parts.push(`- line ${n.lineNo}${key.startsWith('old') ? ' (removed line)' : ''}: ${n.text}\n  > ${n.line.trim().slice(0, 160)}`);
      parts.push('');
