  useEffect(() => {
    const el = box.current?.querySelector<HTMLElement>(sel === null ? '.tl-now' : `[data-step="${sel}"]`);
    el?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  }, [sel]);

  const first = list[0]?.at;
  const span = first ? (list[list.length - 1]?.at || first) - first : 0;

