        {list.length > 0 && (
          <span className="faint tnum">
            {plural(changing.length, 'change')} · {span > 60_000 ? duration(span) : 'just started'}
          </span>
        )}
        <div className="grow" />
        {sel !== null && (
          <button className="btn sm ghost" onClick={() => pick(null)} title="Back to the present (End)">
            <ArrowDownToLine size={13} /> Now
