  copy.style.pointerEvents = 'none';
  copy.classList.add(className);
  document.body.append(copy);
  let done = false;
  const finish = () => {
    if (done) return;
    done = true;
    copy.remove();
  };
  copy.addEventListener('animationend', (e) => e.target === copy && finish());
