  }
  dirty.clear();
  set({ rt });
}

function patchRt(id: string, patch: Partial<Runtime>) {
  const cur = get().rt[id] || { rev: 0, loaded: false, loading: false };
  set({ rt: { ...get().rt, [id]: { ...cur, ...patch } } });
}

