      const last = this.items[this.items.length - 1];
      if (!(last && last.kind === 'notice' && last.tag === 'interrupt')) this.add({ kind: 'notice', id: nid('n'), rev: 0, level: 'info', text: 'Interrupted', tag: 'interrupt' }, null);
