        return;
      }
      case 'local_command_output':
        if (m.content?.trim()) this.add({ kind: 'command-output', id: nid('co'), rev: 0, text: m.content }, null);
        return;
      case 'api_retry': {
        const last = this.items[this.items.length - 1];
