          last.count = (last.count || 1) + 1;
          this.bump(last);
        } else {
          const n: NoticeItem = { kind: 'notice', id: nid('n'), rev: 0, level: 'warning', text, tag: 'retry', detail: m.error == null ? undefined : String(m.error) };
